#' RD Covariate Balance / Placebo Outcomes
#'
#' 
#' @param data .
#' @param covs .
#' @param running .
#' @param cluster .
#' @param cutVar .
#' @param cutoff .
#' @param p .
#' @param bwselect .
#' @param kernel .
#' @param vce .
#' @param level .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$balance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$balPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$balance$asDF}
#'
#' \code{as.data.frame(results$balance)}
#'
#' @export
rdcov <- function(
    data,
    covs,
    running,
    cluster,
    cutVar,
    cutoff = 0,
    p = 1,
    bwselect = "mserd",
    kernel = "triangular",
    vce = "nn",
    level = 95,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rdcov requires jmvcore to be installed (restart may be required)")

    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(cutVar)) cutVar <- jmvcore::resolveQuo(jmvcore::enquo(cutVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(cutVar), cutVar, NULL))


    options <- rdcovOptions$new(
        covs = covs,
        running = running,
        cluster = cluster,
        cutVar = cutVar,
        cutoff = cutoff,
        p = p,
        bwselect = bwselect,
        kernel = kernel,
        vce = vce,
        level = level,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdcovClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

